const test = require('node:test');
const assert = require('node:assert/strict');
const { parseCounts } = require('../quantities.cjs');
test('every token is parsed in decimal independent of its array index', () => {
  assert.deepEqual(parseCounts('8 12 24'),[8,12,24]);
  assert.deepEqual(parseCounts('08 010 20'),[8,10,20]);
  assert.deepEqual(parseCounts(' 5\t16\n32  7 '),[5,16,32,7]);
  assert.deepEqual(parseCounts('0 0 0 0'),[0,0,0,0]);
  assert.deepEqual(parseCounts('9 9 9'),[9,9,9]);
  assert.deepEqual(parseCounts('001'),[1]);
  assert.deepEqual(parseCounts(''),[]);
  assert.deepEqual(parseCounts(' \t\n'),[]);
  const tokens = Array.from({length:40},(_,index) => String(index+10));
  assert.deepEqual(parseCounts(tokens.join(' ')),Array.from({length:40},(_,index) => index+10));
});

